      SUBROUTINE DECFRMC---- DECODE FORMAL ARGUMENT LISTC-----------------------------------------------------------------------      INCLUDE 'FORCNT.CIN'      INCLUDE 'FORDAT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'C-----------------------------------------------------------------------      CHARACTER*15    KNAME      LOGICAL         FLAGC-----------------------------------------------------------------------      DATA MXFORM /20/C      ERROR = .FALSE.      NFORM = 0CC---- ARGUMENT NAMEC  100 CALL RDNEXT      IF (ENDFIL) GO TO 400      CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        GO TO 200      ENDIF      CALL RDLOOK(KNAME,15,FNAME,1,NFORM,IFORM)      IF (IFORM .NE. 0) THEN        CALL RDFAIL        WRITE (IECHO,920) KNAME(1:LNAME)        GO TO 200      ENDIFCC---- SEPARATOR?C      CALL RDNEXT      IF (ENDFIL) GO TO 400      CALL RDTEST(',)',FLAG)      IF (FLAG) GO TO 200CC---- ALLOCATE CELL TO ARGUMENTC      NFORM = NFORM + 1      IF (NFORM .GT. MXFORM) THEN        WRITE (IECHO,930)        NFAIL = NFAIL + 1        CALL RDEND        STOP      ENDIF      FNAME(NFORM) = KNAME      GO TO 300CC---- ERROR RECOVERYC  200 CALL RDFIND(',);')      IF (ENDFIL) GO TO 400      ERROR = .TRUE.  300 IF (ITEM .EQ. ',') GO TO 100      IF (ITEM .EQ. ')') CALL RDNEXT  400 CONTINUE      RETURNC-----------------------------------------------------------------------  910 FORMAT(' *** ERROR *** FORMAL ARGUMENT NAME EXPECTED'/' ')  920 FORMAT(' *** ERROR *** DUPLICATE FORMAL ARGUMENT "',A,'"'/' ')  930 FORMAT (' *** ERROR *** TOO MANY FORMAL ARGUMENTS'/' ')C-----------------------------------------------------------------------      END